&lt;span class="nx"&gt;data&lt;/span&gt; &lt;span class="s2"&gt;"aws_iam_policy_document"&lt;/span&gt; &lt;span class="s2"&gt;"firehose_assume"&lt;/span&gt; &lt;span class="p"&gt;{&lt;/span&gt;
